// Bearings detail canvas - generated by bin/fm-bearings-board.sh build from the
// same payload as the bearings board. Regenerated on every build; edits here
// are overwritten. Every value below is data rendered as text, never markup.
import {
  Code,
  Divider,
  H1,
  H2,
  Link,
  Pill,
  Row,
  Stack,
  Stat,
  Table,
  Text,
  type TableRowTone,
} from "cursor/canvas";

type Blocker = { readonly id: string; readonly title: string | null };

type DetailItem = {
  readonly section: string;
  readonly anchor: string;
  readonly id: string;
  readonly repo: string | null;
  readonly title: string;
  readonly status: string;
  readonly waits_on: string;
  readonly since_label: string;
  readonly since: string | null;
  readonly owner: string | null;
  readonly blockers: readonly Blocker[];
  readonly report: string | null;
  readonly report_url: string | null;
  readonly report_path: string | null;
  readonly pr_url: string | null;
  readonly filed: string | null;
};

type Detail = {
  readonly schema: string;
  readonly home: string;
  readonly generated: string;
  readonly charted_more: number;
  readonly charted_warning_more: number;
  readonly charted: readonly DetailItem[];
  readonly landed: readonly DetailItem[];
};

const DETAIL: Detail =
__FM_BEARINGS_DETAIL_MODEL__
;

const HEADERS = ["What it is", "Status", "Waits on", "Since", "Owner", "Blockers", "Report", "PR", "Filed"];

// Wrapping untrusted values in an element child keeps React's DOM text escaping
// while bypassing Text's inline markdown parser on raw string children.
function plain(value: string) {
  return <span>{value}</span>;
}

function rowTone(item: DetailItem): TableRowTone {
  return item.status === "needs repair" ? "danger" : "neutral";
}

function orNone(value: string | null, none: string) {
  return value === null ? (
    <Text tone="tertiary" size="small">{none}</Text>
  ) : (
    <Text size="small">{plain(value)}</Text>
  );
}

function rowOf(item: DetailItem) {
  return [
    <Stack gap={2}>
      <Text weight="semibold">{plain(item.title)}</Text>
      {item.repo === null ? null : <Text tone="secondary" size="small">{plain(item.repo)}</Text>}
    </Stack>,
    <Pill size="sm" active={item.status === "ready" || item.status === "landed"}>{plain(item.status)}</Pill>,
    <Text size="small">{plain(item.waits_on)}</Text>,
    <Stack gap={0}>
      <Text tone="tertiary" size="small">{plain(item.since_label)}</Text>
      {orNone(item.since, "Not recorded")}
    </Stack>,
    orNone(item.owner, "Not recorded"),
    item.blockers.length === 0 ? (
      <Text tone="tertiary" size="small">None</Text>
    ) : (
      <Stack gap={2}>
        {item.blockers.map((b, i) => (
          <div key={`${i}:${b.id}`}>
            <Text size="small">
              {plain(b.title ?? b.id)} {b.title === null ? null : <Code>{b.id}</Code>}
            </Text>
          </div>
        ))}
      </Stack>
    ),
    item.report_url !== null ? (
      <Link href={item.report_url}>{item.report_url}</Link>
    ) : item.report_path !== null ? (
      <Link href={`file://${item.report_path.split("/").map(encodeURIComponent).join("/")}`}>{plain(item.report_path)}</Link>
    ) : (
      <Text tone="tertiary" size="small">Not recorded</Text>
    ),
    item.pr_url === null ? (
      <Text tone="tertiary" size="small">None recorded</Text>
    ) : (
      <Link href={item.pr_url}>{item.pr_url}</Link>
    ),
    orNone(item.filed, "Not recorded"),
  ];
}

export default function BearingsDetailCanvas() {
  const queued = DETAIL.charted.filter((item) => item.status !== "needs repair");
  const ready = queued.filter((item) => item.status === "ready").length;
  const repairs = DETAIL.charted.length - queued.length;
  return (
    <Stack gap={20} style={{ padding: 20 }}>
      <Stack gap={4}>
        <H1>Charted Next and Recently Landed</H1>
        <Text tone="secondary" size="small">
          <span>From the bearings board for {DETAIL.home}, built {DETAIL.generated}.</span>
        </Text>
      </Stack>
      <Row gap={24} wrap>
        <Stat value={String(queued.length + DETAIL.charted_more)} label="Charted next" tone="info" />
        <Stat value={String(ready)} label="Ready to start" tone="success" />
        {repairs > 0 ? <Stat value={String(repairs)} label="Records needing repair" tone="danger" /> : null}
        <Stat value={String(DETAIL.landed.length)} label="Recently landed" tone="success" />
      </Row>
      <Stack gap={8}>
        <H2>Charted Next</H2>
        {queued.length === 0 && DETAIL.charted_more === 0 ? (
          <Text tone="secondary" size="small">Nothing is queued.</Text>
        ) : null}
        {DETAIL.charted.length > 0 ? (
          <Table headers={HEADERS} rows={DETAIL.charted.map(rowOf)} rowTone={DETAIL.charted.map(rowTone)} striped />
        ) : null}
        {DETAIL.charted_more > 0 ? (
          <Text tone="tertiary" size="small">
            {`+${DETAIL.charted_more} more queued ${DETAIL.charted_more === 1 ? "item was" : "items were"} left out when this board was built.`}
          </Text>
        ) : null}
        {DETAIL.charted_warning_more > 0 ? (
          <Text tone="tertiary" size="small">
            {`+${DETAIL.charted_warning_more} more repair ${DETAIL.charted_warning_more === 1 ? "warning was" : "warnings were"} left out when this board was built.`}
          </Text>
        ) : null}
      </Stack>
      <Divider />
      <Stack gap={8}>
        <H2>Recently Landed</H2>
        {DETAIL.landed.length === 0 ? (
          <Text tone="secondary" size="small">No recent completions are in the current baseline.</Text>
        ) : (
          <Table headers={HEADERS} rows={DETAIL.landed.map(rowOf)} rowTone={DETAIL.landed.map(rowTone)} striped />
        )}
      </Stack>
    </Stack>
  );
}
